import { extendTheme } from '@chakra-ui/react';
import { mode } from '@chakra-ui/theme-tools';

// Custom theme for the market analysis platform
const loveableTheme = extendTheme({
  config: {
    initialColorMode: 'dark',
    useSystemColorMode: false,
  },
  fonts: {
    heading: `'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol"`,
    body: `'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol"`,
  },
  colors: {
    brand: {
      50: '#e3f2fd',
      100: '#bbdefb',
      200: '#90caf9',
      300: '#64b5f6',
      400: '#42a5f5',
      500: '#2196f3',
      600: '#1e88e5',
      700: '#1976d2',
      800: '#1565c0',
      900: '#0d47a1',
    },
    success: {
      50: '#e8f5e8',
      100: '#c8e6c9',
      200: '#a5d6a7',
      300: '#81c784',
      400: '#66bb6a',
      500: '#4caf50',
      600: '#43a047',
      700: '#388e3c',
      800: '#2e7d32',
      900: '#1b5e20',
    },
    danger: {
      50: '#ffebee',
      100: '#ffcdd2',
      200: '#ef9a9a',
      300: '#e57373',
      400: '#ef5350',
      500: '#f44336',
      600: '#e53935',
      700: '#d32f2f',
      800: '#c62828',
      900: '#b71c1c',
    },
    purple: {
      50: '#f3e5f5',
      100: '#e1bee7',
      200: '#ce93d8',
      300: '#ba68c8',
      400: '#ab47bc',
      500: '#9c27b0',
      600: '#8e24aa',
      700: '#7b1fa2',
      800: '#6a1b9a',
      900: '#4a148c',
    },
    orange: {
      50: '#fff3e0',
      100: '#ffe0b2',
      200: '#ffcc80',
      300: '#ffb74d',
      400: '#ffa726',
      500: '#ff9800',
      600: '#fb8c00',
      700: '#f57c00',
      800: '#ef6c00',
      900: '#e65100',
    },
  },
  styles: {
    global: (props) => ({
      body: {
        bg: mode('gray.50', 'gray.900')(props),
        color: mode('gray.800', 'gray.100')(props),
        lineHeight: 'tall',
      },
      '*::placeholder': {
        color: mode('gray.400', 'gray.500')(props),
      },
      '*, *::before, &::after': {
        borderColor: mode('gray.200', 'gray.700')(props),
      },
    }),
  },
  components: {
    Button: {
      baseStyle: {
        fontWeight: 'medium',
        borderRadius: 'lg',
        _focus: {
          boxShadow: '0 0 0 3px rgba(66, 165, 245, 0.6)',
        },
      },
      variants: {
        solid: (props) => ({
          bg: mode(`${props.colorScheme}.500`, `${props.colorScheme}.600`)(props),
          color: 'white',
          _hover: {
            bg: mode(`${props.colorScheme}.600`, `${props.colorScheme}.700`)(props),
            transform: 'translateY(-2px)',
            boxShadow: 'lg',
          },
          _active: {
            bg: mode(`${props.colorScheme}.700`, `${props.colorScheme}.800`)(props),
            transform: 'translateY(0)',
          },
          transition: 'all 0.2s',
        }),
        outline: (props) => ({
          borderColor: mode(`${props.colorScheme}.200`, `${props.colorScheme}.700`)(props),
          color: mode(`${props.colorScheme}.600`, `${props.colorScheme}.400`)(props),
          _hover: {
            bg: mode(`${props.colorScheme}.50`, `${props.colorScheme}.900`)(props),
            borderColor: mode(`${props.colorScheme}.300`, `${props.colorScheme}.600`)(props),
            transform: 'translateY(-1px)',
          },
          transition: 'all 0.2s',
        }),
        ghost: (props) => ({
          color: mode(`${props.colorScheme}.600`, `${props.colorScheme}.400`)(props),
          _hover: {
            bg: mode(`${props.colorScheme}.50`, `${props.colorScheme}.900`)(props),
            transform: 'translateY(-1px)',
          },
          transition: 'all 0.2s',
        }),
      },
      defaultProps: {
        colorScheme: 'brand',
      },
    },
    Card: {
      baseStyle: (props) => ({
        container: {
          bg: mode('white', 'gray.800')(props),
          borderRadius: 'xl',
          boxShadow: mode('xl', 'dark-lg')(props),
          borderWidth: '1px',
          borderColor: mode('gray.200', 'gray.700')(props),
          transition: 'all 0.2s',
          _hover: {
            boxShadow: mode('2xl', 'dark-xl')(props),
          },
        },
      }),
    },
    Input: {
      variants: {
        outline: (props) => ({
          field: {
            borderRadius: 'lg',
            borderColor: mode('gray.300', 'gray.600')(props),
            _hover: {
              borderColor: mode('brand.400', 'brand.500')(props),
            },
            _focus: {
              borderColor: mode('brand.500', 'brand.400')(props),
              boxShadow: '0 0 0 1px var(--chakra-colors-brand-500)',
            },
          },
        }),
      },
    },
    Badge: {
      baseStyle: {
        borderRadius: 'full',
        fontWeight: 'medium',
        fontSize: 'xs',
        textTransform: 'uppercase',
        letterSpacing: 'wider',
      },
    },
    Progress: {
      baseStyle: {
        track: {
          borderRadius: 'full',
        },
        filledTrack: {
          borderRadius: 'full',
        },
      },
    },
    Alert: {
      variants: {
        subtle: (props) => ({
          container: {
            borderRadius: 'lg',
            borderWidth: '1px',
            borderColor: mode(`${props.colorScheme}.200`, `${props.colorScheme}.700`)(props),
          },
        }),
      },
    },
    Tabs: {
      variants: {
        enclosed: (props) => ({
          tab: {
            borderRadius: 'lg',
            fontWeight: 'medium',
            _selected: {
              bg: mode('white', 'gray.800')(props),
              borderColor: mode('gray.200', 'gray.700')(props),
              borderBottomColor: mode('white', 'gray.800')(props),
            },
          },
          tabpanel: {
            borderRadius: 'lg',
            borderWidth: '1px',
            borderColor: mode('gray.200', 'gray.700')(props),
            bg: mode('white', 'gray.800')(props),
          },
        }),
      },
    },
  },
  shadows: {
    outline: '0 0 0 3px rgba(66, 165, 245, 0.6)',
  },
});

export default loveableTheme;
